LR = 2e-3            # peak LR
WARMUP_FRAC = 0.03   # fraction of the wall-clock budget spent on linear warmup
FINAL_LR_FRAC = 0.0  # cosine decays to LR * FINAL_LR_FRAC at the end of the budget
LOG_EVERY = 25


def lr_at(frac):
    """Time-based schedule: linear warmup then cosine decay, frac = elapsed / budget in [0, 1]."""
    frac = min(max(frac, 0.0), 1.0)
    if frac < WARMUP_FRAC:
        return LR * (frac / WARMUP_FRAC)
    p = (frac - WARMUP_FRAC) / (1.0 - WARMUP_FRAC)
    return LR * (FINAL_LR_FRAC + (1.0 - FINAL_LR_FRAC) * 0.5 * (1.0 + math.cos(math.pi * p)))

